// Approved SICARÚ artwork, encoded as a multi-resolution ICO.
// Kept self-contained so the favicon never depends on an external image host.
const icon = Buffer.from("", "base64");

export const dynamic = "force-static";

export function GET() {
  return new Response(new Uint8Array(icon), {
    headers: {
      "Content-Type": "image/x-icon",
      "Cache-Control": "public, max-age=3600, must-revalidate",
    },
  });
}
